import{d as g,C as a,o as d,c as h,a3 as o,E as r,j as n,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第九章","description":"《正易心法》第九章——乾坤错杂，乃生六子：一阴入乾之下中上生巽离兑，一阳入坤之下中上生震坎艮，六子皆乾坤破体，入位决定卦性。","frontmatter":{"title":"正易心法·第九章","description":"《正易心法》第九章——乾坤错杂，乃生六子：一阴入乾之下中上生巽离兑，一阳入坤之下中上生震坎艮，六子皆乾坤破体，入位决定卦性。","category":"guide","aliases":["正易心法第九章","乾坤错杂乃生六子","破体"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-09.md","filePath":"yijing/zheng-yi-xin-fa/chapter-09.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-09.md"},f=g({...c,setup(u){const e=[{id:"z9-01",label:"一、六子即破体",showLabel:!0,sentences:[["乾坤",{text:"错杂",glossary:"cuoza"},"，乃生",{text:"六子",glossary:"liuzi"},"。六子则是，乾坤",{text:"破体",glossary:"poti"},"。"]],note:["乾坤阴阳交错混杂，于是生出六个子卦；六子卦的生成，正是乾坤纯体被打破的结果。（这是第八章「三代祖孙之别」的第一次具体展开：乾坤是祖，六子是孙，「破体」是生成机制。它回答了一个根本问题——为什么是这八个卦，而不是别的？因为每个子卦由「乾坤哪个位置被打破」决定。）"]},{id:"z9-02",label:"二、乾破体生三女",showLabel:!0,sentences:[["乾三画奇，纯阳也。一阴杂于下，是为巽；杂于中，是为离；杂于上，是为兑。"]],note:["乾卦三爻皆奇（阳），是纯阳之体：一阴混入初爻，成为巽；混入中爻，成为离；混入上爻，成为兑。（入位决定卦性：阴入下则巽——柔顺潜伏在根基，故「入」；阴入中则离——阴藏阳中，故「丽」；阴入上则兑——柔在其上、开口于顶，故「说」。）"]},{id:"z9-03",label:"三、皆破乾之纯阳",showLabel:!0,sentences:[["巽、离、兑，皆破乾之纯阳也。"]],note:["巽、离、兑，都是乾的纯阳之体被打破的结果。（三女卦的「破」是同一件事的三个位置：一阴入乾，入得越上，阳气越往外走——下则潜伏、中则含藏、上则外浮。这与《说卦传》「巽一索而得女，故谓之长女」是同一结果、不同路径。）"]},{id:"z9-04",label:"四、坤破体生三男",showLabel:!0,sentences:[["坤三画偶，纯阴也。一阳杂于下，是为震；杂于中，是为坎；杂于上，是为艮。"]],note:["坤卦三爻皆偶（阴），是纯阴之体：一阳混入初爻，成为震；混入中爻，成为坎；混入上爻，成为艮。（入位决定卦性：阳入下则震——阳气从地下爆发，故「动」；阳入中则坎——阳被阴包围，故「陷」；阳入上则艮——阳气凝止于顶，故「止」。）"]},{id:"z9-05",label:"五、皆破坤之纯体",showLabel:!0,sentences:[["震、坎、艮，皆破坤之纯体也。"]],note:["震、坎、艮，都是坤的纯阴之体被打破的结果。（「破体」不是破坏，而是生育：乾坤相交如父母交合，一阴入乾是母气渗入父体，一阳入坤是父气渗入母体，六子由此诞生。这与《系辞传》「乾道成男，坤道成女」相吻合，但麻衣更进一步——具体说明哪个位置被破，生出哪个卦。）"]},{id:"z9-06",label:"六、以人身求之",showLabel:!0,sentences:[["若更以人身求之，理自",{text:"昭然",glossary:"zhaoran"},"。"]],note:["若再用人体来对应验证，道理自然昭然若揭。（《说卦传》的对应是：乾为首、坤为腹、震为足、巽为股、坎为耳、离为目、艮为手、兑为口。麻衣的意思：人体的结构，正是乾坤破体的自然写照——不需要文字解释，对照卦画与人体，「理自昭然」。）"]}],s=[{id:"cuoza",term:"错杂",pinyin:"cuò zá",meaning:"交错混杂。指乾坤的阴阳相互渗入。"},{id:"liuzi",term:"六子",pinyin:"liù zǐ",meaning:"六个子卦：震、巽、坎、离、艮、兑。由乾坤破体而生。"},{id:"poti",term:"破体",pinyin:"pò tǐ",meaning:"破坏纯粹的本体。纯阳／纯阴被一爻异类打破——不是破坏，而是生育。"},{id:"zhaoran",term:"昭然",pinyin:"zhāo rán",meaning:"明白显著，一目了然。"}];return(b,t)=>{const i=a("DaoTextReading"),l=a("DaoKeywordCards");return d(),h("div",null,[t[0]||(t[0]=o(`<h1 id="正易心法·第九章" tabindex="-1">正易心法·第九章 <a class="header-anchor" href="#正易心法·第九章" aria-label="Permalink to &quot;正易心法·第九章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是第八章「三代祖孙之别」的<strong>第一次具体展开</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第八章（总纲）：三代祖孙之别</span></span>
<span class="line"><span>第九章（展开）：乾坤是祖，六子是孙，「破体」是生成机制</span></span></code></pre></div><p><strong>核心命题：八卦不是一个平行的集合，而是一个有内在生成逻辑的家族体系——乾坤是根，六子是枝，生成机制是「破体」。</strong></p><p>它回答了一个根本问题：<strong>为什么是这八个卦，而不是其他？为什么震是震、坎是坎，不能互换？</strong></p><p><strong>答案是：每个卦的结构，由它是「乾／坤的哪个位置被打破」来决定——这是自然的，不是人为规定的。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「破体」是一个生命隐喻</strong>——不是破坏，而是生育：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾坤相交     = 父母交合</span></span>
<span class="line"><span>一阴入乾     = 母气（坤）渗入父体（乾）</span></span>
<span class="line"><span>一阳入坤     = 父气（乾）渗入母体（坤）</span></span>
<span class="line"><span>六子诞生     = 破体而生，如同分娩</span></span></code></pre></div><p><strong>入位与卦性的关系</strong>：</p><table tabindex="0"><thead><tr><th>入位</th><th>坤系（阳入坤）</th><th>乾系（阴入乾）</th></tr></thead><tbody><tr><td><strong>入下（初爻）</strong>——根基被占</td><td>震（阳在下，爆发力在根基，故<strong>动</strong>）</td><td>巽（阴在下，柔顺潜伏在根基，故<strong>入</strong>）</td></tr><tr><td><strong>入中（二爻）</strong>——核心被占</td><td>坎（阳在中，被阴包围，故<strong>陷</strong>）</td><td>离（阴在中，被阳包围，故<strong>丽</strong>）</td></tr><tr><td><strong>入上（三爻）</strong>——顶端被占</td><td>艮（阳在上，凝止于顶，故<strong>止</strong>）</td><td>兑（阴在上，开口于顶，故<strong>说</strong>）</td></tr></tbody></table><p><strong>这正是麻衣批评「只作八字说」的反面示范</strong>——不是死记「震动巽入坎陷离丽艮止兑说」，而是从卦画结构推导出为什么震是动、坎是陷。</p><p><strong>与《说卦传》一字之差</strong>：</p><table tabindex="0"><thead><tr><th></th><th>《说卦传》</th><th>麻衣道者</th></tr></thead><tbody><tr><td>生成描述</td><td>「一<strong>索</strong>而得男」</td><td>「一阴／阳<strong>杂</strong>于下／中／上」</td></tr><tr><td>语气</td><td>主动求取，有人为意志</td><td>自然混入，阴阳运动的必然</td></tr></tbody></table><blockquote><p>「索」是主动求取，「杂」是自然混入——<strong>这一字之差，正是「合为自然」（第五章）与人为安排的核心分歧。</strong></p></blockquote><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先自己画一遍：拿乾☰，把初、中、上三爻依次换成阴，看是不是巽、离、兑；</li><li>同样拿坤☷，把三爻依次换成阳，看是不是震、坎、艮；</li><li>再读「以人身求之」——对照《说卦传》的身体对应，看「破体」逻辑能不能解释它。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>错杂与破体</strong>：乾坤纯体被异类爻打破，乃生六子。</li><li><strong>乾破体生三女</strong>：阴入下中上 → 巽、离、兑。</li><li><strong>坤破体生三子</strong>：阳入下中上 → 震、坎、艮。</li><li><strong>入位决定卦性</strong>：下则动／入，中则陷／丽，上则止／说。</li><li><strong>以人身求之</strong>：人体结构正是破体的写照，「理自昭然」。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),r(i,{colophon:"乾坤错杂 · 乃生六子 · 破体生育 · 入位定性",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第九章原文",sections:e,glossary:s}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(l,{items:[{term:"破体",pinyin:["pò","tǐ"],meaning:"纯阳／纯阴被一爻异类打破。不是破坏，而是生育——乾坤相交而六子诞生的机制。"},{term:"一阴杂于下中上",pinyin:["yī","yīn"],meaning:"阴入乾之初爻为巽、入中爻为离、入上爻为兑——三女卦的生成。"},{term:"一阳杂于下中上",pinyin:["yī","yáng"],meaning:"阳入坤之初爻为震、入中爻为坎、入上爻为艮——三男卦的生成。"},{term:"入位定性",pinyin:["rù","wèi"],meaning:"入下则动（震）／入（巽）；入中则陷（坎）／丽（离）；入上则止（艮）／说（兑）。位置决定卦性。"},{term:"以人身求之",pinyin:["rén","shēn"],meaning:"乾为首、坤为腹、震为足、巽为股、坎为耳、离为目、艮为手、兑为口——人体结构正是破体的写照。"}]}),t[3]||(t[3]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>第八章「三代祖孙」的首次具体展开</strong>，用「破体」这一机制精确描述六子的生成。</p><p><strong>核心命题</strong>：八卦不是一个平行的集合，而是<strong>一个有内在生成逻辑的家族体系</strong>——乾坤是根，六子是枝，生成机制是「破体」。</p><p>它回答了根本问题：<strong>为什么是这八个卦？为什么震是震、坎是坎，不能互换？</strong> 答案是：<strong>每个卦的结构，由它是「乾坤的哪个位置被打破」来决定。</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「破体」是生命隐喻</strong>——乾坤相交如父母交合，一阴入乾是母气渗入父体，一阳入坤是父气渗入母体，<strong>六子诞生 = 破体而生</strong>。</p><p><strong>入位与卦性的关系</strong>：</p><table tabindex="0"><thead><tr><th>入位</th><th>坤系</th><th>乾系</th></tr></thead><tbody><tr><td>入下</td><td>震（动）</td><td>巽（入）</td></tr><tr><td>入中</td><td>坎（陷）</td><td>离（丽）</td></tr><tr><td>入上</td><td>艮（止）</td><td>兑（说）</td></tr></tbody></table><p><strong>这正是麻衣批评「只作八字说」的反面示范</strong>——不是死记「震动巽入」，而是<strong>从卦画结构推导出为什么</strong>。</p><p><strong>与《说卦传》的一字之差</strong>：《说卦传》说「一<strong>索</strong>而得男」（主动求取，有人为意志），麻衣说「一阴／阳<strong>杂</strong>于下／中／上」（自然混入，阴阳运动的必然）——<strong>这一字之差，正是「合为自然」与人为安排的分歧。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>自己动手画一遍（乾破体、坤破体），比读十遍都有效；</li><li>记住一句话：<strong>「位置即意义」</strong>——同一个爻，落在不同位置，卦性完全不同；</li><li>带着一个问题往下读：<strong>为什么是「耳」？</strong>（见下）</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>乾坤阴阳交错混杂，于是生出六个子卦；六子卦的生成，正是乾坤纯体被打破的结果。</p><p>乾卦三爻皆奇（阳），是纯阳之体：一阴混入初爻，成为巽；混入中爻，成为离；混入上爻，成为兑。巽、离、兑，都是乾的纯阳之体被打破的结果。</p><p>坤卦三爻皆偶（阴），是纯阴之体：一阳混入初爻，成为震；混入中爻，成为坎；混入上爻，成为艮。震、坎、艮，都是坤的纯阴之体被打破的结果。</p><p>若再用人体来对应验证，道理自然昭然若揭。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第九章给「八卦」补上了<strong>生成的道理</strong>——<strong>不是八个平列的符号，而是一对父母生了六个孩子；每个孩子像谁，取决于父母身上哪个位置被打破了。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「破体」这个词</strong>——它不是破坏，是生育。<strong>同一个词，在这个语境里是「生」，在别的语境里是「毁」——这又是「找落处」。</strong></li><li><strong>「位置即意义」</strong>——入下是动、入中是陷、入上是止。<strong>这条规律不只在卦里，在我手上的事里也一样：同一个动作，落在不同的位置，效果完全不同。</strong></li><li><strong>「索」与「杂」的一字之差</strong>——《说卦传》说求取，麻衣说混入。<strong>一个通向人为，一个通向自然。</strong> 我读到这里才真正懂第五章「合为自然」的分量。</li><li><strong>与第一章的呼应</strong>——第一章说「坎得乾中爻，故月自天之中而运」，第九章给出了生成论基础：<strong>坎是坤被一阳入中。</strong> 第一章是结论，第九章是推导——<strong>读到第九章，才真正明白第一章在说什么。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>坎是坤被一阳入中，坎对应「耳」——为什么「阳入中」对应的是耳，而不是眼或口？</strong> 我的初步想法：<strong>耳是「孔窍深陷、内藏听觉」——外为阴（耳之外形），内为窍（中虚），而声音的接受不靠外放而靠近纳。</strong> 坎为「陷」为「险」，耳在五官中最不主动：眼可开合、口可言说，<strong>唯有耳不能关闭，外界一切声音都听得进</strong>——这最像「阳陷于阴中」的那个「陷」字：<strong>被动承受，不得不听。</strong> 至于为什么不是离（目）——<strong>目是「丽」，附丽于外物而放光；耳是「陷」，内藏而受声。一放一收，正好相对。</strong> 这个推论未必是定论，但它是我用卦画结构推出来的，而不是从《说卦传》背来的。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「坎得乾中爻」（本章给出生成论基础）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-05">第五章 · 无穷妙义</a> — 「合为自然」（「杂」与「索」的一字之差）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-12">第十二章</a> — 八字是结构原则（本章是其生成论根据）</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「乾，天也，故称乎父」与「一索而得男」：麻衣代的「索」为「杂」</li></ul>',24))])}}});export{y as __pageData,f as default};
